const applyCookies = require("../module/applyCookies");
const applyHeaders = require("../module/applyHeaders");
const closeBrowserContext = require("../module/closeBrowserContext");
const readTurnstileToken = require("../module/readTurnstileToken");

function solveTurnstileMin({ url, proxy, siteKey, cookies, headers }) {
  return new Promise(async (resolve, reject) => {
    // 最小资源模式需要两个核心参数：
    // 1. url：用于让浏览器进入目标站点对应的域名环境。
    // 2. siteKey：用于渲染 Cloudflare Turnstile 组件并生成 token。
    if (!url) return reject("缺少 url 参数");
    if (!siteKey) return reject("缺少 siteKey 参数");

    // 每次任务创建独立 browser context，代理、cookie、localStorage 等状态都只在本任务内生效。
    // 这里不新建浏览器进程，可以降低启动成本；context 关闭后状态会被清理。
    const context = await global.browser
      .createBrowserContext({
        proxyServer: proxy ? `http://${proxy.host}:${proxy.port}` : undefined, // https://pptr.dev/api/puppeteer.browsercontextoptions
      })
      .catch(() => null);
    if (!context) return reject("创建浏览器上下文失败");

    let isResolved = false;

    // endpoint 级超时保护。Turnstile 页面、代理或网络卡住时，主动关闭 context 防止资源泄漏。
    var cl = setTimeout(async () => {
      if (!isResolved) {
        await closeBrowserContext(context, "turnstile-min 模式处理超时");
        reject("处理超时");
      }
    }, global.timeOut || 60000);

    try {
      const page = await context.newPage();

      // 代理认证必须在任何导航之前执行，否则首个请求可能已经因为代理鉴权失败而中断。
      if (proxy?.username && proxy?.password)
        await page.authenticate({
          username: proxy.username,
          password: proxy.password,
        });

      await applyCookies(page, url, cookies);
      await applyHeaders(page, headers);

      // 开启请求拦截后，可以把目标页面的主文档请求替换成本地 fakePage.html。
      // 这样浏览器仍然处在目标 url 的 origin 下，但页面内容只加载 Turnstile 组件，
      // 不再下载目标站点原本的 CSS、JS、图片等资源。
      await page.setRequestInterception(true);

      page.on("request", async (request) => {
        if (
          [url, url + "/"].includes(request.url()) &&
          request.resourceType() === "document"
        ) {
          // fakePage.html 中的 <site-key> 占位符会被调用方传入的 siteKey 替换。
          await request.respond({
            status: 200,
            contentType: "text/html",
            body: String(
              require("fs").readFileSync("./src/data/fakePage.html")
            ).replace(/<site-key>/g, siteKey),
          });
        } else {
          // 非主文档请求继续放行，尤其是 Turnstile 官方脚本需要正常加载。
          await request.continue();
        }
      });

      // 访问目标 url 会触发上面的主文档拦截，最终浏览器实际渲染的是 fakePage.html。
      await page.goto(url, {
        waitUntil: "domcontentloaded",
      });

      // fakePage.html 在 Turnstile callback 中会写入隐藏 input。
      // 公共读取函数会在挑战 iframe 重建时自动短重试。
      const token = await readTurnstileToken(page, global.tokenTimeOut || 60000);

      isResolved = true;
      clearTimeout(cl);
      // token 太短通常表示 Turnstile 没有真正返回有效结果，直接作为失败处理。
      if (!token || token.length < 10) {
        await closeBrowserContext(context, "turnstile-min 模式获取到无效 token");
        return reject("获取 token 失败");
      }
      await closeBrowserContext(context, "turnstile-min 模式处理完成");
      return resolve({ token });
    } catch (e) {
      if (!isResolved) {
        // 异常路径也必须关闭 context，否则长时间运行后会堆积页面和网络连接。
        clearTimeout(cl);
        await closeBrowserContext(context, "turnstile-min 模式处理异常");
        reject(e.message);
      }
    }
  });
}
module.exports = solveTurnstileMin;
